import React from 'react';

const outfitImages = {
  'Modern Classic': 'https://i.pinimg.com/564x/87/02/45/8702453c85f0cc2d4cc3b946d379ac4c.jpg',
  'Retro Streetwear': 'https://i.pinimg.com/564x/58/2f/64/582f64cbf070d6c7354d2e2b46f59e92.jpg',
  'Boho Chic': 'https://i.pinimg.com/564x/93/40/5e/93405e72e3aeabbb6e21f6f2936c3959.jpg'
};


export default function Result({ result, onReset }) {
  const imageUrl = outfitImages[result.style] || '';

  return (
    <div>
      <h2>🎨 Your Style DNA</h2>
      <p><strong>Style:</strong> {result.style}</p>
      <p><strong>Decade:</strong> {result.decade}</p>
      <p><strong>Item:</strong> {result.item}</p>

      {imageUrl && (
        <img
          src={imageUrl}
          alt={result.style}
          style={{ width: '100%', maxWidth: '400px', marginTop: '20px', borderRadius: '10px' }}
        />
      )}

      <br /><br />
      <button onClick={onReset}>🔁 Take Quiz Again</button>
    </div>
  );
}
